-- =============================================================
-- dict_word 增加 levels 多标签列：一个词可同时属于多个词库（如 abandon 既是四级也是高考词）
-- csv 档位顺序：zhongkao(中考),gaokao(高考),cet4(四级),cet6(六级)
-- 回填后各等级池=完整大纲词表；选级过滤改用 FIND_IN_SET(levels)
-- 「不重复学」不受影响：取新词时按用户已学集合排除，与词库池划分无关
-- 幂等可重复执行；重复执行报 Duplicate column 忽略即可（MySQL 8 不支持 ADD COLUMN IF NOT EXISTS）
-- 用法：DBeaver 打开本文件（编码 UTF-8），不选中任何内容，Alt+X 执行整个脚本
-- =============================================================
USE `word_spirit`;

-- 1) 加列（幂等：仅当 levels 列不存在时执行）
SET @has_levels = (SELECT COUNT(*) FROM information_schema.COLUMNS
  WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'dict_word' AND COLUMN_NAME = 'levels');
SET @sql_add_levels = IF(@has_levels = 0,
  'ALTER TABLE `dict_word` ADD COLUMN `levels` VARCHAR(64) NOT NULL DEFAULT '''' COMMENT ''词库多标签csv: zhongkao,gaokao,cet4,cet6'' AFTER `level`',
  'SELECT 1');
PREPARE stmt_add_levels FROM @sql_add_levels;
EXECUTE stmt_add_levels;
DEALLOCATE PREPARE stmt_add_levels;

-- 2) 回填标签（7547 个词将带标签）
